import java.io.*;
import java.util.*;

public class Main {
    static class DSU {
        int[] parent, rank;
        DSU(int n) {
            parent = new int[n + 1];
            rank = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
            }
        }
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
        boolean union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return false;
            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
            return true;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        int[] u = new int[M];
        int[] v = new int[M];
        int[] t = new int[M];

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            u[i] = Integer.parseInt(st.nextToken());
            v[i] = Integer.parseInt(st.nextToken());
            t[i] = Integer.parseInt(st.nextToken());
        }

        DSU dsu = new DSU(N);
        boolean hydroCycle = false;

        // Hydroways (type 1) cannot be removed, so they must form a forest.
        for (int i = 0; i < M; i++) {
            if (t[i] == 1) {
                if (!dsu.union(u[i], v[i])) {
                    hydroCycle = true;
                }
            }
        }

        if (hydroCycle) {
            System.out.println("N");
            return;
        }

        // Process roads (type 2). Count how many must be removed to keep the graph acyclic.
        int removedRoads = 0;
        for (int i = 0; i < M; i++) {
            if (t[i] == 2) {
                if (!dsu.union(u[i], v[i])) {
                    removedRoads++;
                }
            }
        }

        // At most K roads could have been built in the last K years.
        if (removedRoads <= K) {
            System.out.println("S");
        } else {
            System.out.println("N");
        }
    }
}
